package cl.bolsillo.app;
import android.app.*;import android.appwidget.*;import android.content.*;import android.content.pm.*;import android.provider.Settings;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
final class NativeSettings {
 static void fieldFocus(Activity a,EditText field){Glass.editor(field);field.setOnFocusChangeListener((v,focused)->{android.graphics.drawable.Drawable fill=Glass.material(a,241,15,Glass.secondary(a));if(focused){android.graphics.drawable.GradientDrawable edge=Glass.round(a,android.graphics.Color.TRANSPARENT,15);edge.setStroke(Math.max(1,Glass.dp(a,1)),Glass.alpha(Glass.accent(a),125));fill=new android.graphics.drawable.LayerDrawable(new android.graphics.drawable.Drawable[]{fill,edge});}field.setBackground(fill);});}
 static ArrayAdapter<String> suggestions(android.content.Context c,List<String> words){return new ArrayAdapter<String>(c,android.R.layout.simple_dropdown_item_1line,words){@Override public View getView(int position,View convert,ViewGroup parent){View row=super.getView(position,convert,parent);if(row instanceof TextView){TextView text=(TextView)row;text.setTypeface(Glass.font(c,400));text.setTextSize(15);text.setTextColor(Glass.ink(c));text.setMinHeight(Glass.dp(c,48));}return row;}};}
 interface Select{void done(int index);}
 static LinearLayout panel(Activity a,String title){LinearLayout l=Glass.column(a);l.addView(Glass.text(a,title,23,true));return l;}
 static Dialog display(Activity a,LinearLayout l){Dialog d=new SheetDialog(a,l);d.show();return d;}
 static Button action(Activity a,LinearLayout l,String title,Runnable callback){Button b=Glass.button(a,title);l.addView(b);b.setOnClickListener(v->callback.run());return b;}
 static void choose(Activity a,String title,List<String> labels,Select callback){LinearLayout l=panel(a,title);Dialog d=display(a,l);for(int i=0;i<labels.size();i++){final int n=i;Modern.add(l,Modern.item(a,Modern.iconFor(labels.get(i)),labels.get(i),"","",Glass.accent(a),()->{d.dismiss();callback.done(n);}),8);}action(a,l,"Cancelar",d::dismiss);}
 static void info(Activity a,String text){Toast.makeText(a,text,Toast.LENGTH_LONG).show();}
 static EditText input(Activity a,LinearLayout l,String hint,String value){EditText e=new EditText(a);e.setTextColor(Glass.ink(a));e.setHintTextColor(Glass.subtle(a));e.setTextSize(15);e.setTypeface(Glass.font(a,400));e.setFontFeatureSettings("tnum");e.setHint(hint);e.setContentDescription(hint);e.setText(value);e.setSingleLine(true);e.setMinHeight(Glass.dp(a,56));e.setPadding(Glass.dp(a,16),Glass.dp(a,10),Glass.dp(a,16),Glass.dp(a,10));e.setBackground(Glass.material(a,241,15,Glass.secondary(a)));fieldFocus(a,e);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=Glass.dp(a,6);lp.bottomMargin=Glass.dp(a,14);l.addView(e,lp);return e;}
 static AutoCompleteTextView conceptInput(Activity a,LinearLayout l,String hint,String value,List<String> suggestions){AutoCompleteTextView e=new AutoCompleteTextView(a);e.setTextColor(Glass.ink(a));e.setHintTextColor(Glass.subtle(a));e.setTextSize(15);e.setTypeface(Glass.font(a,400));e.setFontFeatureSettings("tnum");e.setHint(hint);e.setContentDescription(hint);e.setText(value);e.setSelection(e.length());e.setSingleLine(true);e.setThreshold(1);e.setMinHeight(Glass.dp(a,56));e.setPadding(Glass.dp(a,16),Glass.dp(a,10),Glass.dp(a,16),Glass.dp(a,10));e.setBackground(Glass.material(a,241,15,Glass.secondary(a)));fieldFocus(a,e);ArrayAdapter<String> adapter=suggestions(a,suggestions);e.setAdapter(adapter);e.setDropDownBackgroundDrawable(Glass.round(a,Glass.dark(a)?0xff25334b:0xfff2f5fc,16));e.setDropDownHeight(Glass.dp(a,260));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=Glass.dp(a,6);lp.bottomMargin=Glass.dp(a,14);l.addView(e,lp);return e;}
 static boolean permission(Activity a){String enabled=Settings.Secure.getString(a.getContentResolver(),"enabled_notification_listeners");if(enabled==null)return false;for(String item:enabled.split(":")){ComponentName n=ComponentName.unflattenFromString(item);if(n!=null&&n.equals(new ComponentName(a,BankNotificationListener.class)))return true;}return false;}
 static JSONArray accounts(Activity a)throws Exception{JSONObject cache=NativeStore.cached(a);if(cache==null)throw new Exception("Abre Bolsillo primero");return QuickEntryDialog.active(cache.getJSONObject("data").getJSONArray("accounts"));}
 static void chooseAccount(Activity a,boolean allowUnknown,SelectAccount callback){try{JSONArray list=accounts(a);List<String> ids=new ArrayList<>(),labels=new ArrayList<>();if(allowUnknown){ids.add("");labels.add("Identificar tarjeta; si falta, preguntarme");}for(int i=0;i<list.length();i++){JSONObject x=list.getJSONObject(i);ids.add(x.getString("id"));labels.add(x.getString("name"));}choose(a,"Cuenta para estos gastos",labels,n->callback.done(ids.get(n)));}catch(Exception e){info(a,e.getMessage());}}
 interface SelectAccount{void done(String id);}
 static void show(MainActivity a){a.navigate("Automático");}
 static void sources(Activity a){if(a instanceof MainActivity){MainActivity host=(MainActivity)a;host.attempt(()->AutomationScreen.selectApps(host));}}
 static void cards(Activity a){if(a instanceof MainActivity){MainActivity host=(MainActivity)a;host.autoTab="Tarjetas";host.navigate("Automático");}}
 static void chooseCategory(Activity a,SelectAccount callback){try{JSONArray cats=NativeStore.cached(a).getJSONObject("data").getJSONArray("categories");List<String> labels=new ArrayList<>(),ids=new ArrayList<>();for(int i=0;i<cats.length();i++){JSONObject x=cats.getJSONObject(i);if(!x.optBoolean("archived")&&"expense".equals(x.optString("type"))){labels.add(x.optString("emoji")+" "+x.getString("name"));ids.add(x.getString("id"));}}choose(a,"Categoría de gasto",labels,n->callback.done(ids.get(n)));}catch(Exception e){info(a,"Configura tus categorías primero");}}
 static void rules(Activity a){try{JSONArray rules=new JSONArray(NativeStore.settings(a).getString("categoryRules","[]"));LinearLayout l=panel(a,"Categorías automáticas");Dialog d=display(a,l);l.addView(Glass.text(a,"Se reconocen comercios habituales de alimentación, transporte, salud, compras y suscripciones. Lo desconocido va a Otros gastos. Tus reglas tienen prioridad.",15,false));for(int i=0;i<rules.length();i++){final int index=i;JSONObject r=rules.getJSONObject(i);action(a,l,"Eliminar regla: "+r.optString("word"),()->{rules.remove(index);NativeStore.settings(a).edit().putString("categoryRules",rules.toString()).apply();d.dismiss();rules(a);});}EditText word=input(a,l,"Comercio o palabra, ej. Netflix","");action(a,l,"Elegir categoría y guardar regla",()->{String w=word.getText().toString().trim();if(w.length()<2||w.length()>80){info(a,"Escribe entre 2 y 80 caracteres");return;}chooseCategory(a,id->{try{rules.put(new JSONObject().put("word",w).put("category",id));NativeStore.settings(a).edit().putString("categoryRules",rules.toString()).apply();d.dismiss();rules(a);}catch(Exception e){info(a,e.getMessage());}});});action(a,l,"Volver",d::dismiss);}catch(Exception e){info(a,e.getMessage());}}
 static void inbox(Activity a){try{JSONObject state=NativeStore.state(a),cache=state.optJSONObject("cache");String owner=cache==null?"":cache.optString("ownerId");JSONArray items=state.optJSONArray("detectionInbox");LinearLayout l=panel(a,"Avisos apartados");Dialog d=display(a,l);l.addView(Glass.text(a,"Estos avisos NO han descontado dinero. Los duplicados se conservan aquí por si fueron dos compras distintas.",15,false));int count=0;if(items!=null)for(int i=items.length()-1;i>=0;i--){JSONObject e=items.getJSONObject(i);if(!owner.equals(e.optString("ownerId")))continue;count++;l.addView(Glass.text(a,BolsilloWidget.money(e.optLong("amount"))+" · "+e.optString("merchant"),18,true));l.addView(Glass.text(a,e.optString("label")+" · "+android.text.format.DateFormat.format("dd/MM HH:mm",e.optLong("at"))+"\n"+e.optString("reason")+(e.optString("last4").isEmpty()?"":" · Tarjeta •"+e.optString("last4")),14,false));action(a,l,e.optString("duplicateOf").isEmpty()?"Asignar y registrar":"Es otra compra: registrar aparte",()->chooseAccount(a,false,account->chooseCategory(a,category->{try{e.put("account",account).put("category",category);NativeStore.resolveDetection(a,e.getString("id"),Detection.transaction(a,e,true));NativeSync.run(a,null);BolsilloWidget.updateAll(a);d.dismiss();inbox(a);}catch(Exception err){info(a,err.getMessage());}})));action(a,l,"Descartar este aviso",()->{try{NativeStore.resolveDetection(a,e.getString("id"),null);d.dismiss();inbox(a);}catch(Exception err){info(a,err.getMessage());}});}if(count==0)l.addView(Glass.text(a,"No hay avisos pendientes aquí.",16,false));action(a,l,"Volver",d::dismiss);}catch(Exception e){info(a,e.getMessage());}}
 static void test(Activity a){LinearLayout l=panel(a,"Probar una notificación");Dialog d=display(a,l);l.addView(Glass.text(a,"Pega el título y texto de un aviso. Esta prueba no guarda movimientos ni conserva el texto.",15,false));EditText title=input(a,l,"Título","");EditText text=input(a,l,"Texto del aviso","");text.setSingleLine(false);TextView result=Glass.text(a,"",15,false);l.addView(result);action(a,l,"Analizar aviso",()->{BankNotificationParser.Candidate p=BankNotificationParser.movement(title.getText()+"\n"+text.getText(),title.getText().toString(),false,true,"");result.setText(p==null?"No se reconoce un movimiento CLP. Revisa la redacción o añade una regla.":"Tipo: "+(p.type.equals("income")?"Ingreso":p.type.equals("expense")?"Gasto":"Revisar")+"\nMonto: "+(p.amount==0?"Por verificar":BolsilloWidget.money(p.amount))+"\nDetalle: "+p.merchant+(p.review?"\nRequiere confirmación":"")+(p.reason==null||p.reason.isEmpty()?"":"\n"+p.reason));});action(a,l,"Cerrar",d::dismiss);}
 static void widgets(Activity a){WidgetPreferences.manage(a);}
}


